// On-demand LinkedIn text generator with free-form prompt + optional sources + market-brief research
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { resolveTextProvider, xaiErrorMessage } from "../_shared/ai-text.ts";
import { gatherSourceContext, type SourceInput } from "../_shared/web-sources.ts";
import {
  detectLanguageOverride,
  detectMarketBrief,
  gatherMarketBriefContext,
  marketBriefSystemPrompt,
  wantsXPost,
} from "../_shared/market-research.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};
const json = (s: number, b: unknown) => new Response(JSON.stringify(b), { status: s, headers: { ...corsHeaders, "Content-Type": "application/json" } });

const LANG_NAMES: Record<string, string> = {
  fr: "French (Français)", en: "English", es: "Spanish (Español)",
  de: "German (Deutsch)", ar: "Arabic (العربية)",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  try {
    const { prompt, currentText, imageUrl, mode, sources, savedSourceIds, language } = await req.json();
    const supabase = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    const auth = req.headers.get("Authorization");
    if (!auth) return json(401, { success: false, error: "Unauthorized" });
    const { data: u } = await supabase.auth.getUser(auth.replace("Bearer ", ""));
    const userId = u.user?.id;
    if (!userId) return json(401, { success: false, error: "Unauthorized" });

    const { data: s } = await supabase.from("user_settings")
      .select("post_model, use_byok, openai_api_key, xai_api_key, gemini_api_key, firecrawl_api_key, tone_instructions")
      .eq("user_id", userId).maybeSingle();

    let resolvedSources: SourceInput[] = Array.isArray(sources) ? sources : [];
    if (Array.isArray(savedSourceIds) && savedSourceIds.length) {
      const { data: saved } = await supabase
        .from("content_sources")
        .select("id, source_type, value")
        .eq("user_id", userId)
        .in("id", savedSourceIds);
      for (const r of saved || []) {
        if (r.source_type === "url" || r.source_type === "keyword" || r.source_type === "idea") {
          resolvedSources.push({ type: r.source_type as SourceInput["type"], value: r.value });
        }
      }
    }

    if (!resolvedSources.length) {
      const { data: enabled } = await supabase
        .from("content_sources")
        .select("source_type, value")
        .eq("user_id", userId)
        .eq("enabled", true)
        .limit(8);
      for (const r of enabled || []) {
        if (r.source_type === "url" || r.source_type === "keyword" || r.source_type === "idea") {
          resolvedSources.push({ type: r.source_type as SourceInput["type"], value: r.value });
        }
      }
    }

    const promptText = typeof prompt === "string" ? prompt.trim() : "";
    const includeX = wantsXPost(promptText);
    const langCode = detectLanguageOverride(promptText) || String(language || "fr");
    const langName = LANG_NAMES[langCode] || LANG_NAMES.fr;

    let sourceContext = "";
    let sourceProvider: "firecrawl" | "open" = "open";
    let queryCount = 0;
    let researchUrls: string[] = [];

    if (mode !== "improve" && (marketBrief || resolvedSources.length || promptText.length > 12)) {
      if (detectMarketBrief(promptText)) {
        const brief = await gatherMarketBriefContext({
          prompt: promptText,
          sources: resolvedSources,
          firecrawlKey: s?.firecrawl_api_key,
        });
        sourceContext = brief.context;
        sourceProvider = brief.provider;
        queryCount = brief.queryCount;
        researchUrls = brief.freshUrls;
      } else {
        const planned = resolvedSources.length
          ? resolvedSources
          : [{ type: "keyword" as const, value: promptText.slice(0, 180) }];
        const gathered = await gatherSourceContext(planned, { firecrawlKey: s?.firecrawl_api_key });
        sourceContext = gathered.context;
        sourceProvider = gathered.provider;
        researchUrls = gathered.freshUrls;
      }
    }

    const { model, url, key } = resolveTextProvider(s?.post_model || "google/gemini-3-flash-preview", s);

    const hasResearch = sourceContext.trim().length > 80;
    const sys = detectMarketBrief(promptText)
      ? `${marketBriefSystemPrompt(langName, hasResearch, includeX)}
${s?.tone_instructions ? `\nExtra brand voice from settings (do not override figure rules):\n${s.tone_instructions}` : ""}`
      : `You write engaging LinkedIn posts in the user's voice.
LANGUAGE: Write the entire post (title, body, hashtags, CTA) strictly in ${langName}.
Rules: 150-300 words, 5-7 hashtags, sparing emojis, end with a CTA/question.
${s?.tone_instructions ? `User tone:\n${s.tone_instructions}` : ""}
${hasResearch
  ? "You HAVE live web research. Ground claims in it. Do not invent figures."
  : "No live web research. Do not invent live prices."}
${includeX ? "Also fill x_post (≤280 chars)." : "Set x_post to empty string."}
Return JSON via the write_post tool.`;

    const sourceBlock = hasResearch
      ? `\n\n=== RESEARCH (Tier-1 preferred; use only these facts for numbers) ===\n${sourceContext.substring(0, 20000)}\n=== END RESEARCH ===`
      : "\n\n(No research snippets retrieved.)";

    let userMsg: unknown;
    if (mode === "improve" && currentText) {
      userMsg = `Rewrite and polish this draft into a great LinkedIn post:\n\n${currentText}\n\n${promptText ? `Extra instructions: ${promptText}` : ""}${sourceBlock}`;
    } else if (imageUrl) {
      userMsg = [
        { type: "text", text: `Write a LinkedIn post about this image. ${promptText || ""}${sourceBlock}` },
        { type: "image_url", image_url: { url: imageUrl } },
      ];
    } else {
      userMsg = `${promptText || "Write a thought-provoking LinkedIn post on a topic relevant to my industry."}${sourceBlock}

Deliver:
- LinkedIn post as specified
${includeX ? "- X/Twitter version ≤280 characters" : ""}
- verify_before_publish: checklist of items the human must confirm before publishing (sources, timestamps, settlement vs intraday)`;
    }

    const res = await fetch(url, {
      method: "POST",
      headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        model,
        messages: [{ role: "system", content: sys }, { role: "user", content: userMsg }],
        tools: [{
          type: "function",
          function: {
            name: "write_post",
            description: "Write a LinkedIn market post (and optional X post) grounded in research",
            parameters: {
              type: "object",
              properties: {
                title: { type: "string", description: "Short internal title (≤80 chars)" },
                content: { type: "string", description: "Full LinkedIn post body with sources line and hashtags" },
                x_post: { type: "string", description: "Optional X/Twitter post ≤280 chars, or empty" },
                sources_line: { type: "string", description: "Compact sources attribution line" },
                verify_before_publish: {
                  type: "array",
                  items: { type: "string" },
                  description: "Checklist of facts/timestamps the human should verify before publishing",
                },
              },
              required: ["title", "content", "x_post", "sources_line", "verify_before_publish"],
              additionalProperties: false,
            },
          },
        }],
        tool_choice: { type: "function", function: { name: "write_post" } },
      }),
    });
    if (!res.ok) {
      if (url.startsWith("https://api.x.ai/")) return json(res.status, { success: false, error: xaiErrorMessage(res.status) });
      if (res.status === 429) return json(429, { success: false, error: "Rate limit exceeded." });
      if (res.status === 402) return json(402, { success: false, error: "Add credits to your workspace." });
      const t = await res.text();
      return json(500, { success: false, error: `AI error [${res.status}]: ${t}` });
    }

    const data = await res.json();
    const tc = data.choices?.[0]?.message?.tool_calls?.[0];
    if (!tc) return json(500, { success: false, error: "AI returned no structured data" });
    const out = JSON.parse(tc.function.arguments);
    return json(200, {
      success: true,
      title: out.title,
      content: out.content,
      x_post: out.x_post || "",
      sources_line: out.sources_line || "",
      verify_before_publish: Array.isArray(out.verify_before_publish) ? out.verify_before_publish : [],
      usedSources: resolvedSources.length,
      sourceProvider,
      hadWebContext: hasResearch,
      queryCount,
      researchUrlCount: researchUrls.length,
      languageUsed: langCode,
      marketBrief: detectMarketBrief(promptText),
    });
  } catch (e) {
    console.error("compose-text error", e);
    return json(500, { success: false, error: e instanceof Error ? e.message : "Failed" });
  }
});

/**
 * Turn a free-form user brief into concrete web research queries + writing mode.
 * Goal: feed the model enough Tier-1 snippets to write a CommoHedge-style market post.
 */

import { gatherSourceContext, scrapeUrl, searchKeyword, type SourceInput } from "./web-sources.ts";

const TIER1_SITES = [
  "reuters.com",
  "bloomberg.com",
  "cnbc.com",
  "ft.com",
  "wsj.com",
  "eia.gov",
  "investing.com",
  "tradingeconomics.com",
];

const COMMODITY_QUERIES = [
  "Brent crude oil price today",
  "WTI crude oil price today",
  "TTF natural gas Europe price EUR/MWh",
  "Henry Hub natural gas price",
  "gold price USD/oz today",
  "silver platinum price today",
  "copper LME price today",
  "CBOT wheat corn soybean price",
  "US dollar index DXY yields today",
  "commodity market movers today energy metals agriculture",
];

export function detectMarketBrief(prompt: string): boolean {
  const p = prompt.toLowerCase();
  return /commodit|marché|market|reuters|bloomberg|cnbc|eia|brent|wti|ttf|hedge|commohedge|settlement|intraday|oil|gas|gold|copper|wheat|fed\b|prix|clôture|bourse/.test(p);
}

/** Prefer language asked inside the prompt over the UI selector. */
export function detectLanguageOverride(prompt: string): string | null {
  const p = prompt.toLowerCase();
  if (/en anglais|in english|linkedin (post )?in english|english (post|version)/.test(p)) return "en";
  if (/en français|in french|linkedin (post )?in french|français/.test(p)) return "fr";
  if (/en español|in spanish|espagnol/.test(p)) return "es";
  if (/auf deutsch|in german|allemand/.test(p)) return "de";
  if (/بالعربية|in arabic|arabe/.test(p)) return "ar";
  return null;
}

export function wantsXPost(prompt: string): boolean {
  return /\b(x|twitter|tweet)\b|280\s*caract|280\s*char/i.test(prompt);
}

function siteFilter(): string {
  return TIER1_SITES.map((s) => `site:${s}`).join(" OR ");
}

/** Build focused keyword searches from the user brief (never dump the whole prompt as one query). */
export function buildResearchKeywords(prompt: string, extra: SourceInput[] = []): string[] {
  const out: string[] = [];
  const filter = `(${siteFilter()})`;

  // Always include commodity desk coverage when this is a market brief
  if (detectMarketBrief(prompt)) {
    for (const q of COMMODITY_QUERIES) {
      out.push(`${q} ${filter}`);
    }
  }

  // User-provided keywords stay as-is (and get a Tier-1 variant)
  for (const s of extra) {
    if (s.type === "keyword" && s.value.trim()) {
      const v = s.value.trim().slice(0, 160);
      out.push(v);
      if (!/site:/i.test(v)) out.push(`${v} ${filter}`);
    }
  }

  // Light extraction of asset names mentioned in the prompt
  const mentioned = prompt.match(
    /\b(Brent|WTI|TTF|Henry Hub|gold|silver|platinum|copper|wheat|corn|soy|soybean|Fed|ECB|DXY|LME|CBOT|MATIF|natgas|natural gas|crude)\b/gi,
  );
  if (mentioned) {
    for (const m of [...new Set(mentioned.map((x) => x.toLowerCase()))].slice(0, 6)) {
      out.push(`${m} price today OR settlement ${filter}`);
    }
  }

  // Deduplicate, cap
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const q of out) {
    const key = q.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    unique.push(q);
    if (unique.length >= 12) break;
  }
  return unique;
}

/**
 * Deep research for market briefs:
 * 1) multi-query search on Tier-1 domains
 * 2) scrape the best article URLs so the model sees actual figures, not titles only
 */
export async function gatherMarketBriefContext(opts: {
  prompt: string;
  sources: SourceInput[];
  firecrawlKey?: string | null;
}): Promise<{ context: string; freshUrls: string[]; provider: "firecrawl" | "open"; queryCount: number }> {
  const keywords = buildResearchKeywords(opts.prompt, opts.sources);
  const urlSources = opts.sources.filter((s) => s.type === "url");
  const ideaSources = opts.sources.filter((s) => s.type === "idea");

  const planned: SourceInput[] = [
    ...ideaSources,
    ...urlSources,
    ...keywords.map((value) => ({ type: "keyword" as const, value })),
  ];

  // First pass: search + user URLs
  const first = await gatherSourceContext(planned, {
    firecrawlKey: opts.firecrawlKey,
    maxUrls: 6,
    maxKeywords: 10,
    urlSnippetChars: 2200,
  });

  // Second pass: scrape top unique article URLs from search hits for real numbers
  const articleUrls = first.freshUrls
    .filter((u) => /^https?:\/\//i.test(u))
    .filter((u, i, arr) => arr.indexOf(u) === i)
    .filter((u) => !/google\.com\/search|duckduckgo\.com/i.test(u))
    .slice(0, 6);

  const articleChunks: string[] = [];
  await Promise.all(articleUrls.map(async (url) => {
    const md = await scrapeUrl(url, opts.firecrawlKey);
    if (md && md.length > 120) {
      articleChunks.push(`# Article extract: ${url}\n\n${md.substring(0, 2800)}`);
    }
  }));

  // Also run a few high-signal searches and attach hit lists explicitly labeled
  const hitBlocks: string[] = [];
  for (const q of keywords.slice(0, 8)) {
    const hits = await searchKeyword(q, opts.firecrawlKey, 4);
    if (!hits.length) continue;
    hitBlocks.push(
      `# Headlines for query: ${q}\n\n` +
        hits.map((h) => `- ${h.title} — ${h.description} (${h.url})`).join("\n"),
    );
  }

  const context = [
    first.context,
    hitBlocks.join("\n\n---\n\n"),
    articleChunks.join("\n\n---\n\n"),
  ].filter(Boolean).join("\n\n---\n\n");

  return {
    context: context.substring(0, 28000),
    freshUrls: [...new Set([...first.freshUrls, ...articleUrls])],
    provider: first.provider,
    queryCount: keywords.length,
  };
}

export function marketBriefSystemPrompt(langName: string, hasResearch: boolean, includeX: boolean): string {
  return `You are the markets desk writer for CommoHedge (commohedge.com).
You write factual commodity / macro LinkedIn posts for professional hedgers — NOT motivational fluff, NOT process lectures.

LANGUAGE: Write LinkedIn (and X if requested) in ${langName}.

TARGET LINKEDIN STRUCTURE (follow closely):
1. Hook (1–2 lines) — what moved and why it matters
2. Themed paragraphs with REAL figures when present in research: Energy / Metals / Agriculture / Macro (Fed, USD, yields)
3. Pattern / takeaway for hedgers (short)
4. Soft CTA → commohedge.com
5. Sources line with outlets + date context (e.g. "Sources: Reuters, Bloomberg… Morning readings; … closes.")
6. 5–8 relevant hashtags
7. Disclaimer if needed: "For information only, not investment advice."

HARD RULES ON FIGURES:
- Use ONLY numbers, % moves, contract levels, storage %, vote counts, etc. that appear in the RESEARCH block.
- For every price, prefer saying whether it is a settlement/close or an intraday/last print when the research allows it.
- If research is thin for an asset, OMIT that asset or say data was not available — never invent.
- Prefer Tier-1 names: Reuters, Bloomberg, CNBC, EIA, exchange settlements (CME/CBOT/LME/ICE), official agencies.
${hasResearch
    ? "RESEARCH IS ATTACHED below the user request. Ground the post in it. Prefer the densest, most recent snippets with explicit prices."
    : "NO usable research was retrieved. Do NOT invent a market wrap. Return a short post explaining that live Tier-1 figures were unavailable, plus a verify_before_publish checklist."}

STYLE: Concise, desk-like English (or requested language). Like a morning note, not a thought-leadership essay.
Avoid generic lines such as "Commodity desks do not need another hot take" or pure methodology without numbers.
${includeX ? "Also produce x_post: max 280 characters, one punchy market line + key figure if available + CommoHedge mention optional." : "Set x_post to empty string."}

Return JSON via the write_post tool only.`;
}

/**
 * Web source gathering: Firecrawl when a key is available, otherwise free open fallbacks
 * (Jina Reader for URLs, Google News RSS + DuckDuckGo HTML for keyword search).
 */

export type SourceInput = { type: "url" | "keyword" | "idea"; value: string };

export type GatherOptions = {
  /** Prefer user's BYOK Firecrawl key, then env FIRECRAWL_API_KEY. */
  firecrawlKey?: string | null;
  maxUrls?: number;
  maxKeywords?: number;
  /** Skip search results whose URL is in this set (schedules dedupe). */
  usedUrls?: Set<string>;
  urlSnippetChars?: number;
};

function resolveFirecrawlKey(explicit?: string | null): string {
  return (explicit ?? "").trim() || (Deno.env.get("FIRECRAWL_API_KEY") ?? "").trim();
}

function stripTags(html: string): string {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

function decodeXml(s: string): string {
  return s
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

/** Scrape a single URL → markdown/text. */
export async function scrapeUrl(url: string, firecrawlKey?: string | null): Promise<string | null> {
  const fc = resolveFirecrawlKey(firecrawlKey);
  if (fc) {
    try {
      const r = await fetch("https://api.firecrawl.dev/v2/scrape", {
        method: "POST",
        headers: { Authorization: `Bearer ${fc}`, "Content-Type": "application/json" },
        body: JSON.stringify({ url, formats: ["markdown"], onlyMainContent: true, waitFor: 1500 }),
      });
      if (r.ok) {
        const d = await r.json();
        const md = d.data?.markdown || d.markdown;
        if (md) return String(md);
      }
    } catch (e) {
      console.warn("firecrawl scrape fail", url, e);
    }
  }

  // Free: Jina Reader (no API key required for basic use)
  try {
    const r = await fetch(`https://r.jina.ai/${url}`, {
      headers: { Accept: "text/plain", "User-Agent": "market-pulse-poster/1.0" },
    });
    if (r.ok) {
      const text = await r.text();
      if (text.trim().length > 80) return text;
    }
  } catch (e) {
    console.warn("jina scrape fail", url, e);
  }

  // Last resort: raw HTML → text
  try {
    const r = await fetch(url, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; MarketPulseBot/1.0)", Accept: "text/html" },
      redirect: "follow",
    });
    if (!r.ok) return null;
    const html = await r.text();
    const text = stripTags(html);
    return text.length > 80 ? text : null;
  } catch (e) {
    console.warn("raw scrape fail", url, e);
    return null;
  }
}

export type SearchHit = { title: string; description: string; url: string };

/** Keyword web search → list of hits. */
export async function searchKeyword(query: string, firecrawlKey?: string | null, limit = 3): Promise<SearchHit[]> {
  const fc = resolveFirecrawlKey(firecrawlKey);
  if (fc) {
    try {
      const r = await fetch("https://api.firecrawl.dev/v2/search", {
        method: "POST",
        headers: { Authorization: `Bearer ${fc}`, "Content-Type": "application/json" },
        body: JSON.stringify({ query, limit: Math.max(limit, 5), tbs: "qdr:w" }),
      });
      if (r.ok) {
        const d = await r.json();
        const results = d.data || d.web?.results || [];
        const hits = results
          .map((x: { title?: string; description?: string; url?: string }) => ({
            title: x.title || "",
            description: x.description || "",
            url: x.url || "",
          }))
          .filter((x: SearchHit) => x.url);
        if (hits.length) return hits.slice(0, limit);
      }
    } catch (e) {
      console.warn("firecrawl search fail", query, e);
    }
  }

  // Free: Google News RSS
  try {
    const rssUrl =
      `https://news.google.com/rss/search?q=${encodeURIComponent(query)}&hl=en-US&gl=US&ceid=US:en`;
    const r = await fetch(rssUrl, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; MarketPulseBot/1.0)", Accept: "application/rss+xml, application/xml, text/xml" },
    });
    if (r.ok) {
      const xml = await r.text();
      const items = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/gi)].slice(0, limit + 2);
      const hits: SearchHit[] = [];
      for (const m of items) {
        const block = m[1];
        const title = decodeXml((block.match(/<title>([\s\S]*?)<\/title>/i)?.[1] || "").trim());
        const link = decodeXml((block.match(/<link>([\s\S]*?)<\/link>/i)?.[1] || "").trim());
        const desc = stripTags(decodeXml((block.match(/<description>([\s\S]*?)<\/description>/i)?.[1] || "").trim()));
        if (link) hits.push({ title, description: desc.slice(0, 400), url: link });
      }
      if (hits.length) return hits.slice(0, limit);
    }
  } catch (e) {
    console.warn("google news rss fail", query, e);
  }

  // Free: DuckDuckGo HTML
  try {
    const r = await fetch(`https://html.duckduckgo.com/html/?q=${encodeURIComponent(query)}`, {
      headers: {
        "User-Agent": "Mozilla/5.0 (compatible; MarketPulseBot/1.0)",
        Accept: "text/html",
      },
    });
    if (r.ok) {
      const html = await r.text();
      const hits: SearchHit[] = [];
      const re = /<a[^>]+class="result__a"[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>[\s\S]*?(?:class="result__snippet"[^>]*>([\s\S]*?)<\/(?:a|td|div)>)?/gi;
      let m: RegExpExecArray | null;
      while ((m = re.exec(html)) && hits.length < limit) {
        let href = m[1];
        // DDG wraps redirects: //duckduckgo.com/l/?uddg=<encoded>
        const uddg = href.match(/[?&]uddg=([^&]+)/);
        if (uddg) href = decodeURIComponent(uddg[1]);
        hits.push({
          title: stripTags(m[2]),
          description: stripTags(m[3] || "").slice(0, 400),
          url: href,
        });
      }
      if (hits.length) return hits;
    }
  } catch (e) {
    console.warn("duckduckgo search fail", query, e);
  }

  return [];
}

/** Build markdown context from mixed sources (ideas + urls + keywords). */
export async function gatherSourceContext(
  sources: SourceInput[],
  opts: GatherOptions = {},
): Promise<{ context: string; freshUrls: string[]; provider: "firecrawl" | "open" }> {
  const firecrawlKey = resolveFirecrawlKey(opts.firecrawlKey);
  const provider = firecrawlKey ? "firecrawl" : "open";
  const maxUrls = opts.maxUrls ?? 4;
  const maxKeywords = opts.maxKeywords ?? 4;
  const snippet = opts.urlSnippetChars ?? 2500;
  const used = opts.usedUrls ?? new Set<string>();
  const chunks: string[] = [];
  const freshUrls: string[] = [];

  const ideas = sources.filter((s) => s.type === "idea").map((s) => s.value).filter(Boolean);
  if (ideas.length) chunks.push(`# Ideas / notes from the user\n\n${ideas.map((i) => `- ${i}`).join("\n")}`);

  const urls = sources.filter((s) => s.type === "url").map((s) => s.value).filter(Boolean).slice(0, maxUrls);
  const keywords = sources.filter((s) => s.type === "keyword").map((s) => s.value).filter(Boolean).slice(0, maxKeywords);

  await Promise.all(urls.map(async (url) => {
    const md = await scrapeUrl(url, firecrawlKey);
    if (md) {
      chunks.push(`# Source: ${url}\n\n${md.substring(0, snippet)}`);
      freshUrls.push(url);
    }
  }));

  await Promise.all(keywords.map(async (kw) => {
    const results = await searchKeyword(kw, firecrawlKey, used.size ? 5 : 3);
    const fresh = results.filter((x) => x.url && !used.has(x.url)).slice(0, 3);
    if (!fresh.length) return;
    const summary = fresh.map((x) => `- ${x.title}: ${x.description} (${x.url})`).join("\n");
    chunks.push(`# Search: ${kw}\n\n${summary}`);
    for (const x of fresh) freshUrls.push(x.url);
  }));

  return { context: chunks.join("\n\n---\n\n"), freshUrls, provider };
}

export type TextSettings = {
  use_byok?: boolean;
  openai_api_key?: string | null;
  xai_api_key?: string | null;
  gemini_api_key?: string | null;
};

function requireByok(settings: TextSettings | null) {
  if (!settings?.use_byok) {
    throw new Error("Active tes propres clés API (BYOK) dans les paramètres pour générer du contenu.");
  }
}

/** Route text generation to the user's BYOK provider (xAI / OpenAI / Gemini). No shared gateway. */
export function resolveTextProvider(model: string, settings: TextSettings | null) {
  if (model.startsWith("xai/")) {
    requireByok(settings);
    if (!settings?.xai_api_key?.trim()) {
      throw new Error("Ajoute et enregistre ta clé API xAI dans les paramètres pour utiliser Grok.");
    }
    return {
      model: model.slice(4),
      url: "https://api.x.ai/v1/chat/completions",
      key: settings.xai_api_key.trim(),
    };
  }

  if (model.startsWith("openai/")) {
    requireByok(settings);
    if (!settings?.openai_api_key?.trim()) {
      throw new Error("Ajoute et enregistre ta clé API OpenAI dans les paramètres.");
    }
    return {
      model: model.slice(7),
      url: "https://api.openai.com/v1/chat/completions",
      key: settings.openai_api_key.trim(),
    };
  }

  if (model.startsWith("google/")) {
    requireByok(settings);
    if (!settings?.gemini_api_key?.trim()) {
      throw new Error("Ajoute et enregistre ta clé API Google Gemini dans les paramètres.");
    }
    return {
      model: model.replace(/^google\//, ""),
      url: "https://generativelanguage.googleapis.com/v1beta/openai/chat/completions",
      key: settings.gemini_api_key.trim(),
    };
  }

  throw new Error(
    `Modèle non supporté: ${model}. Choisis un modèle Gemini, OpenAI ou Grok dans les réglages (BYOK).`,
  );
}

export function normalizeGrokModels(models: unknown, modality: "text" | "image" = "text"): { value: string; label: string }[] {
  if (!Array.isArray(models)) return [];
  const ids = new Set<string>();
  for (const model of models) {
    if (!model || typeof model !== "object") continue;
    const { id, aliases, output_modalities } = model as {
      id?: unknown;
      aliases?: unknown;
      output_modalities?: unknown;
    };
    if (Array.isArray(output_modalities) && !output_modalities.includes(modality)) continue;
    for (const name of [id, ...(Array.isArray(aliases) ? aliases : [])]) {
      if (typeof name === "string" && /^[a-zA-Z0-9._-]+$/.test(name)) ids.add(name);
    }
  }
  return [...ids].sort().map((id) => ({ value: `xai/${id}`, label: `Grok · ${id} (API xAI)` }));
}

export function xaiErrorMessage(status: number) {
  if (status === 401) return "Clé API xAI invalide ou expirée. Remplace-la dans les paramètres.";
  if (status === 402) return "Crédits xAI insuffisants. Recharge ton compte xAI.";
  if (status === 403) return "Accès xAI refusé : vérifie les permissions de ta clé et l’accès au modèle.";
  if (status === 404) return "Ce modèle Grok n’est plus disponible. Actualise la liste dans les paramètres.";
  if (status === 429) return "Limite de requêtes xAI atteinte. Réessaie plus tard.";
  if (status === 503) return "Le modèle Grok est temporairement surchargé. Réessaie plus tard.";
  return `La requête xAI a échoué (${status}). Vérifie le modèle et réessaie.`;
}
